def prog(id,name,role,hyp,tails,paths,changes,pair,od,season='W/S/межсезонье',asmp=None):
    legs=[]
    for line in paths:
        chain=line['airports']
        for n,(a,b) in enumerate(zip(chain,chain[1:]),1):
            legs.append({'leg_template_id':f'{id}:{line["path_id"]}:{n}','origin_airport':a,'destination_airport':b,'weekdays_iso':line['weekdays_iso'],'resource_group':line['resource_group'],'sequence_in_rotation':n,'source_status':'предлагаемый сценарий','unit':'рейс на каждый выбранный день','physical_adjacent_leg':True,'seats_analogue':100,'saleable_seats':None,'assumption_ids':['TJM-A01','TJM-A04']})
    pairs=sorted({'-'.join(sorted([z['origin_airport'],z['destination_airport']])) for z in legs})
    q={'programme_id':id,'programme_version':'TJM-research-v1','name_ru':name,'role':role,'hypothesis_ids':hyp,'status':'STAGE_A_CONSTRUCTED_STAGE_B_CONDITIONAL','period':'2027–2028','design_active_window':'2027-10-01/2028-12-31','season':season,'as_of':ASOF,'source_id':'TJM-S01;TJM-P02;TJM-P03;TJM-P04;TJM-P06','assumption_ids':asmp or ['TJM-A01','TJM-A02','TJM-A04','TJM-A05','TJM-A06','TJM-A09','TJM-A10'],'rotation_paths':paths,'flight_templates':legs,'airport_pairs':pairs,'unique_airport_pairs':len(pairs),'affected_journey_OD':od,'rw_sales_changes':changes,'matched_comparison_id':pair,'resource':{'working_tails_lower_bound':tails,'actual_available_tails':None,'reserve_aircraft':None,'reserve_policy':'Именованный shared reserve или отдельный контракт/борт P03; не считать свободным/бесплатным','crew_TObase_stands_slots':'UNKNOWN; P03','new_aircraft_branch':'только operationally ready календарь; минимумH2 2027; альтернативное использование того же нового борта обязательно','existing_aircraft_branch':'точный KEEP donor и потерянный результат один раз','SJ100_PD8':'отдельный типовой расчёт; ангарSSJнеподтверждаетдопуск','new_Tu214':0},'required_common_inputs':['P02 dated products/full-basket fares + physical leg binding','P03 same N(t), KEEP, assignments, crew, ТО, reserve, airports','P04 cost/event/cash contract, localTJMterms, thresholds','P05 common potential OD pools/month/segment, choice, response','P06 complete P/KEEP context + input acceptance'],'not_claimed':['эксплуатационный допуск','подтверждённый спрос/контракт','финансовый победитель','calibrated P06 result']}
