counts=[]
for p in programmes:
    for yr in [2027,2028]:
        for mon in range(1,13):
            dates=[dt.date(yr,mon,n) for n in range(1,calendar.monthrange(yr,mon)[1]+1)]
            def active(d):
                if p['programme_id']=='TJM-P05':return False
                if p['programme_id']=='TJM-P07':return yr==2028 and 5<=mon<=9
                if p['programme_id'] in ['TJM-P03','TJM-P04']:return d>=dt.date(2027,10,4)
                return d>=dt.date(2027,10,1)
            legs=sum(1 for d in dates if active(d) for l in p['flight_templates'] if d.isoweekday() in l['weekdays_iso'])
            counts.append({'programme_id':p['programme_id'],'month':f'{yr}-{mon:02d}','proposed_physical_legs_before_ops':legs if p['programme_id']!='TJM-P05' else 'UNKNOWN','nominal_seat_segments_analogue':legs*100 if p['programme_id']!='TJM-P05' else 'UNKNOWN','unit':'рейс/месяц;номинальныйкресельныйсегмент/месяц','period':f'{yr}-{mon:02d}','coverage':'только сценарный календарьдизайна;не спрос/acceptedпарк/KEEPдельта','status':'SCENARIO_CALENDAR_NOT_OPS_PASS','source_id':'TJM-P03;TJM-S01','assumption_ids':'TJM-A01;TJM-A05;TJM-A06'})
